module circle_regions(\n    input [1:0] n,\n    input signed [7:0] x1, y1, r1,\n    input signed [7:0] x2, y2, r2,\n    input signed [7:0] x3, y3, r3,\n    output reg [7:0] result\n);\n    // Wires for pair 1-2\n    wire signed [8:0] dx12 = x1 - x2;\n    wire signed [8:0] dy12 = y1 - y2;\n    wire [15:0] dx12_sq = dx12 * dx12;\n    wire [15:0] dy12_sq = dy12 * dy12;\n    wire [15:0] distance_sq_12 = dx12_sq + dy12_sq;\n\n    wire [7:0] sum_12 = r1 + r2;\n    wire [15:0] sum_sq_12 = sum_12 * sum_12;\n    wire [7:0] diff_12 = (r1 >= r2) ? (r1 - r2) : (r2 - r1);\n    wire [15:0] diff_sq_12 = diff_12 * diff_12;\n    wire intersect_two_12 = (distance_sq_12 < sum_sq_12) && (distance_sq_12 > diff_sq_12);\n\n    // Wires for pair 1-3\n    wire signed [8:0] dx13 = x1 - x3;\n    wire signed [8:0] dy13 = y1 - y3;\n    wire [15:0] dx13_sq = dx13 * dx13;\n    wire [15:0] dy13_sq = dy13 * dy13;\n    wire [15:0] distance_sq_13 = dx13_sq + dy13_sq;\n\n    wire [7:0] sum_13 = r1 + r3;\n    wire [15:0] sum_sq_13 = sum_13 * sum_13;\n    wire [7:0] diff_13 = (r1 >= r3) ? (r1 - r3) : (r3 - r1);\n    wire [15:0] diff_sq_13 = diff_13 * diff_13;\n    wire intersect_two_13 = (distance_sq_13 < sum_sq_13) && (distance_sq_13 > diff_sq_13);\n\n    // Wires for pair 2-3\n    wire signed [8:0] dx23 = x2 - x3;\n    wire signed [8:0] dy23 = y2 - y3;\n    wire [15:0] dx23_sq = dx23 * dx23;\n    wire [15:0] dy23_sq = dy23 * dy23;\n    wire [15:0] distance_sq_23 = dx23_sq + dy23_sq;\n\n    wire [7:0] sum_23 = r2 + r3;\n    wire [15:0] sum_sq_23 = sum_23 * sum_23;\n    wire [7:0] diff_23 = (r2 >= r3) ? (r2 - r3) : (r3 - r2);\n    wire [15:0] diff_sq_23 = diff_23 * diff_23;\n    wire intersect_two_23 = (distance_sq_23 < sum_sq_23) && (distance_sq_23 > diff_sq_23);\n\n    // Count intersect_two flags for n=3\n    wire [1:0] count_pairs = {1'b0, intersect_two_12} + {1'b0, intersect_two_13} + {1'b0, intersect_two_23};\n\n    always @* begin\n        case (n)\n            2'b01: result = 8'd2;\n            2'b10: begin\n                if (intersect_two_12) begin\n                    result = 8'd4;\n                end else begin\n                    result = 8'd3;\n                end\n            end\n            2'b11: begin\n                case (count_pairs)\n                    2'd0: result = 8'd4;\n                    2'd1: result = 8'd6;\n                    2'd2: result = 8'd7;\n                    2'd3: result = 8'd8;\n                    default: result = 8'd0;\n                endcase\n            end\n            default: result = 8'd0;\n        endcase\n    end\nendmodule